-- The schema of the real ledger (schema v5 of C:\AI-autonomous\.claude\.state\harness.db), copied whole: 40 tables,
-- 19 indexes, 4 views, in the order the real ledger made them. Tables, indexes: read from its sqlite_master; view
-- bodies: pipeline/adapters/sqlite/ledger_catalog.py. A tool that moves in finds its table here, unchanged.
CREATE TABLE sessions (sid TEXT PRIMARY KEY, started_at INTEGER, last_at INTEGER, epoch INTEGER NOT NULL DEFAULT 0, project TEXT NOT NULL DEFAULT '', harness_ver TEXT NOT NULL DEFAULT '');
CREATE TABLE act_skill_loads (sid TEXT, agent TEXT, skill TEXT, via TEXT, epoch INTEGER, at INTEGER, uid TEXT);
CREATE INDEX act_skill_loads_sid ON act_skill_loads (sid);
CREATE TABLE act_doc_reads (sid TEXT, agent TEXT, service TEXT, doc TEXT, epoch INTEGER, at INTEGER, uid TEXT);
CREATE INDEX act_doc_reads_sid ON act_doc_reads (sid);
CREATE TABLE act_tool_calls (sid TEXT, agent TEXT, tool TEXT, service TEXT, at INTEGER, plan_id INTEGER, uid TEXT);
CREATE INDEX act_tool_calls_at ON act_tool_calls (at);
CREATE INDEX act_tool_calls_sid ON act_tool_calls (sid, at);
CREATE TABLE act_rule_decisions (uid TEXT PRIMARY KEY, sid TEXT, agent TEXT, plan_id INTEGER, rule TEXT, kind TEXT, tool TEXT, service TEXT, verdict TEXT, detail TEXT, at INTEGER);
CREATE INDEX act_rule_decisions_sid ON act_rule_decisions (sid, at);
CREATE TABLE act_notes (sid TEXT, key TEXT, at INTEGER, uid TEXT, PRIMARY KEY (sid, key));
CREATE TABLE act_source_loads (uid TEXT PRIMARY KEY, sid TEXT, agent TEXT, source TEXT, ref TEXT, mode TEXT, at INTEGER);
CREATE INDEX act_source_loads_sid ON act_source_loads (sid, at);
CREATE TABLE rec_plans (id INTEGER PRIMARY KEY AUTOINCREMENT, sid TEXT, sha TEXT, reason TEXT, scope TEXT, services TEXT, status TEXT, at INTEGER, superseded_at INTEGER, uid TEXT, prev_hash TEXT, hash TEXT);
CREATE INDEX rec_plans_sid ON rec_plans (sid, status);
CREATE TABLE rec_plan_services (plan_id INTEGER, service TEXT, base TEXT, at INTEGER, uid TEXT, PRIMARY KEY (plan_id, service));
CREATE TABLE rec_plan_sources (uid TEXT, plan_id INTEGER, source TEXT, ref TEXT, mode TEXT, at INTEGER, PRIMARY KEY (plan_id, source, ref));
CREATE TABLE rec_edits (sid TEXT, plan_id INTEGER, service TEXT, first_at INTEGER, last_at INTEGER, edits INTEGER NOT NULL DEFAULT 0, uid TEXT, PRIMARY KEY (sid, plan_id, service));
CREATE TABLE rec_commits (plan_id INTEGER, service TEXT, commit_sha TEXT, at INTEGER, uid TEXT, prev_hash TEXT, hash TEXT, PRIMARY KEY (plan_id, service, commit_sha));
CREATE TABLE pl_tickets (id TEXT PRIMARY KEY, sid TEXT, seq INTEGER, state TEXT, units TEXT, body TEXT, at INTEGER);
CREATE INDEX pl_tickets_sid ON pl_tickets (sid, seq);
CREATE TABLE pl_approval (sid TEXT PRIMARY KEY, body TEXT, at INTEGER);
CREATE TABLE pl_checks (uid TEXT PRIMARY KEY, sid TEXT, name TEXT, ok INTEGER, at INTEGER);
CREATE INDEX pl_checks_sid ON pl_checks (sid, at);
CREATE TABLE pl_logs (uid TEXT PRIMARY KEY, body TEXT, at INTEGER);
CREATE TABLE pl_docs_state (service TEXT, sid TEXT, body TEXT, at INTEGER, PRIMARY KEY (service, sid));
CREATE TABLE pl_plan_extras (plan_id INTEGER PRIMARY KEY, body TEXT);
CREATE TABLE pl_git_audit (uid TEXT PRIMARY KEY, sid TEXT, kind TEXT, tickets TEXT, repo TEXT, local_ref TEXT, base TEXT, source TEXT, sha TEXT, remote TEXT, remote_ref TEXT, remote_sha TEXT, files TEXT, at INTEGER, prev_hash TEXT, hash TEXT);
CREATE INDEX pl_git_audit_sha ON pl_git_audit (sha);
CREATE TABLE pl_verify (uid TEXT PRIMARY KEY, sid TEXT, plan_id INTEGER, repo TEXT, files TEXT, tests TEXT, commands TEXT, code INTEGER, ok INTEGER, why TEXT, ms INTEGER, at INTEGER, prev_hash TEXT, hash TEXT);
CREATE INDEX pl_verify_key ON pl_verify (sid, plan_id, repo);
CREATE TABLE pl_file_grants (uid TEXT PRIMARY KEY, sid TEXT, plan_id INTEGER, op TEXT, file TEXT, why TEXT, at INTEGER, prev_hash TEXT, hash TEXT);
CREATE INDEX pl_file_grants_key ON pl_file_grants (sid, plan_id);
CREATE TABLE pl_behaviors (uid TEXT PRIMARY KEY, sid TEXT, plan_id INTEGER, repo TEXT, op TEXT, id TEXT, entry TEXT, at INTEGER, prev_hash TEXT, hash TEXT);
CREATE TABLE pl_asks (sid TEXT, key TEXT, at INTEGER, used INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (sid, key));
CREATE TABLE pl_plan_revs (plan_id TEXT, rev INTEGER, sid TEXT, items TEXT, why TEXT, sha TEXT, at INTEGER, PRIMARY KEY (plan_id, rev));
CREATE INDEX pl_plan_revs_sid ON pl_plan_revs (sid, at);
CREATE TABLE pl_plan_feedback (uid TEXT PRIMARY KEY, plan_id TEXT, rev INTEGER, item TEXT, text TEXT, sid TEXT, at INTEGER);
CREATE TABLE pl_plan_pages (plan_id TEXT PRIMARY KEY, sid TEXT, url TEXT, at INTEGER);
CREATE TABLE pl_plan_events (plan_id TEXT, n INTEGER, sid TEXT, event TEXT, rev INTEGER, step INTEGER, steps INTEGER, ref INTEGER, mirrored INTEGER NOT NULL DEFAULT 0, at INTEGER, PRIMARY KEY (plan_id, n));
CREATE TABLE pl_notes (uid TEXT PRIMARY KEY, kind TEXT, target TEXT, key TEXT, text TEXT, why TEXT, sid TEXT, at INTEGER);
CREATE INDEX pl_notes_key ON pl_notes (kind, target, key, at);
CREATE TABLE pl_session_links (uid TEXT PRIMARY KEY, a TEXT, b TEXT, state TEXT, by_sid TEXT, why TEXT, at INTEGER);
CREATE INDEX pl_session_links_pair ON pl_session_links (a, b, at);
CREATE TABLE pl_turns (sid TEXT, n INTEGER, plan_id INTEGER, ticket TEXT, phase TEXT, prompt_len INTEGER, started_at INTEGER, ended_at INTEGER, PRIMARY KEY (sid, n));
CREATE TABLE pl_prompts (sid TEXT, n INTEGER, text TEXT, chars INTEGER, cut INTEGER, from_peer INTEGER, source TEXT, uuid TEXT, at INTEGER, PRIMARY KEY (sid, n));
CREATE TABLE pl_spans (uid TEXT PRIMARY KEY, sid TEXT, turn INTEGER, parent TEXT, kind TEXT, status TEXT, name TEXT, ms INTEGER, done INTEGER, attrs TEXT, at INTEGER);
CREATE INDEX pl_spans_turn ON pl_spans (sid, turn);
CREATE TABLE pl_usage (sid TEXT, message_id TEXT, token_type TEXT, tokens INTEGER, model TEXT, file TEXT, turn INTEGER, at INTEGER, PRIMARY KEY (sid, message_id, token_type));
CREATE TABLE pl_usage_offsets (sid TEXT, file TEXT, offset INTEGER, at INTEGER, PRIMARY KEY (sid, file));
CREATE TABLE pl_session_meta (sid TEXT PRIMARY KEY, model TEXT, effort TEXT, at INTEGER);
CREATE TABLE pl_prices (model_pattern TEXT, token_type TEXT, rate REAL, per_tokens INTEGER, from_date TEXT, at INTEGER, PRIMARY KEY (model_pattern, token_type, from_date));
CREATE TABLE pl_annotations (uid TEXT PRIMARY KEY, sid TEXT, unit TEXT, ref TEXT, name TEXT, label TEXT, score REAL, explanation TEXT, annotator TEXT, identifier TEXT, at INTEGER);
CREATE INDEX pl_annotations_sid ON pl_annotations (sid, at);
CREATE VIEW pl_plan_facts AS SELECT r.plan_id AS plan_id, r.rev AS revision, r.sid AS sid, r.at AS at, json_extract(r.items, '$.title') AS title, json_extract(r.items, '$.services') AS services, CASE WHEN json_array_length(json_extract(r.items, '$.steps')) > 0 THEN 'steps' ELSE 'single' END AS shape, json_array_length(json_extract(r.items, '$.steps')) AS steps, json_array_length(json_extract(r.items, '$.files')) AS files, json_array_length(json_extract(r.items, '$.tests')) AS tests, json_extract(r.items, '$.overview.problem') AS problem FROM pl_plan_revs r WHERE r.rev = (SELECT MAX(x.rev) FROM pl_plan_revs x WHERE x.plan_id = r.plan_id);
CREATE VIEW pl_retro_rule AS SELECT d.rule AS rule, d.kind AS kind, COUNT(*) AS decisions, SUM(d.verdict = 'deny') AS denials, SUM(d.verdict = 'ask') AS asks, COUNT(DISTINCT d.sid) AS sessions, MAX(d.at) AS last_at, (SELECT d2.tool FROM act_rule_decisions d2 WHERE d2.rule = d.rule AND d2.verdict IN ('deny', 'ask') AND d2.tool <> '' GROUP BY d2.tool ORDER BY COUNT(*) DESC LIMIT 1) AS top_tool FROM act_rule_decisions d WHERE d.rule <> '' GROUP BY d.rule, d.kind;
CREATE VIEW pl_retro_session AS SELECT s.sid AS sid, m.model AS model, m.effort AS effort, (SELECT COUNT(*) FROM pl_turns t WHERE t.sid = s.sid) AS turns, (SELECT COUNT(*) FROM pl_spans p WHERE p.sid = s.sid AND p.kind IN ('tool', 'subagent')) AS calls, (SELECT COUNT(*) FROM pl_spans p WHERE p.sid = s.sid AND p.kind IN ('tool', 'subagent') AND p.status = 'error') AS tool_errors, (SELECT COUNT(*) FROM pl_spans p WHERE p.sid = s.sid AND p.kind IN ('tool', 'subagent') AND p.status = 'denied') AS denials, (SELECT 1.0 * SUM(p.status = 'error') / COUNT(*) FROM pl_spans p WHERE p.sid = s.sid AND p.kind IN ('tool', 'subagent')) AS error_rate, (SELECT COALESCE(SUM(u.tokens), 0) FROM pl_usage u WHERE u.sid = s.sid) AS tokens, (SELECT SUM(u.tokens * pr.rate / pr.per_tokens) FROM pl_usage u JOIN pl_prices pr ON u.model GLOB pr.model_pattern AND pr.token_type = u.token_type AND pr.from_date = (SELECT MAX(p2.from_date) FROM pl_prices p2 WHERE u.model GLOB p2.model_pattern AND p2.token_type = u.token_type AND p2.from_date <= date(u.at / 1000, 'unixepoch')) WHERE u.sid = s.sid) AS cost FROM sessions s LEFT JOIN pl_session_meta m ON m.sid = s.sid;
CREATE VIEW pl_retro_plan AS SELECT f.plan_id AS plan_id, (SELECT GROUP_CONCAT(e.ref) FROM pl_plan_events e WHERE e.plan_id = f.plan_id AND e.event = 'approved') AS plan_ids, (SELECT COUNT(*) FROM pl_plan_revs x WHERE x.plan_id = f.plan_id) AS revisions, (SELECT MIN(e.at) FROM pl_plan_events e WHERE e.plan_id = f.plan_id AND e.event = 'approved') - (SELECT MIN(e.at) FROM pl_plan_events e WHERE e.plan_id = f.plan_id AND e.event = 'waiting') AS approval_ms, (SELECT COUNT(*) FROM act_rule_decisions d WHERE d.verdict = 'deny' AND d.plan_id IN (SELECT e.ref FROM pl_plan_events e WHERE e.plan_id = f.plan_id AND e.event = 'approved')) AS denials, (SELECT COUNT(*) FROM pl_verify v WHERE v.ok = 0 AND v.plan_id IN (SELECT e.ref FROM pl_plan_events e WHERE e.plan_id = f.plan_id AND e.event = 'approved')) AS verify_failed, (SELECT COALESCE(SUM(u.tokens), 0) FROM pl_usage u JOIN pl_turns t ON t.sid = u.sid AND t.n = u.turn WHERE t.plan_id IN (SELECT e.ref FROM pl_plan_events e WHERE e.plan_id = f.plan_id AND e.event = 'approved')) AS tokens, (SELECT SUM(u.tokens * pr.rate / pr.per_tokens) FROM pl_usage u JOIN pl_prices pr ON u.model GLOB pr.model_pattern AND pr.token_type = u.token_type AND pr.from_date = (SELECT MAX(p2.from_date) FROM pl_prices p2 WHERE u.model GLOB p2.model_pattern AND p2.token_type = u.token_type AND p2.from_date <= date(u.at / 1000, 'unixepoch')) JOIN pl_turns t ON t.sid = u.sid AND t.n = u.turn WHERE t.plan_id IN (SELECT e.ref FROM pl_plan_events e WHERE e.plan_id = f.plan_id AND e.event = 'approved')) AS cost FROM pl_plan_facts f;
CREATE TABLE pl_catalog (table_name TEXT, column_name TEXT, kind TEXT, meaning TEXT, writer TEXT, joins TEXT, shape TEXT, PRIMARY KEY (table_name, column_name));
CREATE TABLE pl_git_runs (uid TEXT PRIMARY KEY, sid TEXT, source TEXT, tool TEXT, step TEXT, ok INTEGER, exit INTEGER, reason TEXT, command TEXT, linked_to TEXT, at INTEGER);
CREATE INDEX pl_git_runs_sid ON pl_git_runs (sid, at);
CREATE TABLE pl_children (uid TEXT PRIMARY KEY, plan_id INTEGER, name TEXT, unit TEXT, state TEXT, round INTEGER, sid TEXT, model TEXT, goal TEXT, ac TEXT, at INTEGER);
CREATE INDEX pl_children_plan ON pl_children (plan_id, name, at);
